package com.pointverse.app;

import android.test.InstrumentationTestCase;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

@SuppressWarnings("deprecation")
public final class AudioUnderstandingTest extends InstrumentationTestCase {
    private static byte[] signal(double hz,double seconds,boolean beats){short[] pcm=new short[(int)(16000*seconds)];java.nio.ByteBuffer bytes=java.nio.ByteBuffer.allocate(pcm.length*2).order(java.nio.ByteOrder.LITTLE_ENDIAN);for(int i=0;i<pcm.length;i++){double amplitude=beats?((i%8000)<900?.5:.015):.4;bytes.putShort((short)(Math.sin(2*Math.PI*hz*i/16000)*32767*amplitude));}return CloudTranscription.wav(bytes.array());}
    public void testSilenceHasNoTempoNotesOrInventedKey()throws Exception {AudioUnderstanding.Features f=new AudioUnderstanding.Features();f.accept(CloudTranscription.wav(new byte[16000*2*4]));JSONObject v=f.finish();assertEquals(-120.0,v.getDouble("loudness_db"),.01);assertFalse(v.has("bpm"));assertEquals(0,v.getJSONArray("notes").length());assertFalse(v.has("key"));}
    public void testConcertAFindsFundamentalRatherThanSubharmonic()throws Exception {AudioUnderstanding.Features f=new AudioUnderstanding.Features();f.accept(signal(440,4,false));JSONObject v=f.finish();assertEquals(440,v.getDouble("dominant_pitch_hz"),1);assertTrue(v.getJSONArray("notes").toString().contains("A4"));assertFalse("单个音不能推断调性",v.has("key"));assertTrue(v.getJSONArray("note_sequence").length()>0);assertEquals(4.0,v.getDouble("duration_seconds"),.001);assertTrue(v.getDouble("loudness_db")< -10);}
    public void testBeatTrainProduces120Bpm()throws Exception {AudioUnderstanding.Features f=new AudioUnderstanding.Features();f.accept(signal(440,8,true));JSONObject v=f.finish();assertEquals(120,v.getDouble("bpm"),3);assertTrue(v.getDouble("rhythm_strength")>.5);}
    public void testChunkBoundariesKeepMeasurementsConsistent()throws Exception {AudioUnderstanding.Features all=new AudioUnderstanding.Features(),chunks=new AudioUnderstanding.Features();byte[] wav=signal(440,4,true);all.accept(wav);byte[] pcm=Arrays.copyOfRange(wav,44,wav.length);chunks.accept(CloudTranscription.wav(Arrays.copyOfRange(pcm,0,12346)));chunks.accept(CloudTranscription.wav(Arrays.copyOfRange(pcm,12346,pcm.length)));JSONObject a=all.finish(),b=chunks.finish();assertEquals(a.getDouble("loudness_db"),b.getDouble("loudness_db"),.00001);assertEquals(a.getJSONArray("notes").toString(),b.getJSONArray("notes").toString());}
    public void testRealDecoderAndCloudLabelsProduceReadableDurableContext()throws Exception {File file=fixture();try{AtomicInteger calls=new AtomicInteger();JSONObject value=AudioUnderstanding.analyze(file,"原转写",wav->{calls.incrementAndGet();assertTrue(wav.length<=960044);return new JSONObject().put("model","test-clap").put("labels",new JSONArray().put(new JSONObject().put("label","music").put("score",.8)));});assertEquals(1,calls.get());assertEquals("test-clap",value.getString("cloud_model"));assertTrue(value.getString("semantic_text").contains("音乐"));assertEquals("原转写",value.getString("lyrics"));assertTrue(value.getBoolean("scores_relative"));PointStore.Point p=new PointStore.Point();p.body="原文";p.analysis=value.toString();p.path=null;assertTrue(p.context().contains("音乐"));assertTrue(p.context().startsWith("原文"));assertFalse(p.context().contains("scores_relative"));}finally{file.delete();}}
    public void testCloudFailureStillPreservesAcousticResults()throws Exception {File file=fixture();try{JSONObject v=AudioUnderstanding.analyze(file,"",wav->{throw new java.net.SocketTimeoutException("timeout");});assertTrue(v.has("loudness_db"));assertFalse(v.optString("cloud_error").isEmpty());assertFalse(v.has("cloud_model"));}finally{file.delete();}}
    public void testMalformedCloudReplyKeepsAcousticMeasurements()throws Exception {File file=fixture();try{JSONObject v=AudioUnderstanding.analyze(file,"",wav->new JSONObject().put("labels",new JSONArray()));assertTrue(v.has("loudness_db"));assertFalse(v.optString("cloud_error").isEmpty());assertFalse(v.has("cloud_model"));}finally{file.delete();}}
    public void testLegacyRecordingJsonDoesNotBecomeSemanticSoundText(){assertEquals("",AudioUnderstanding.context("{\"speaker_embedding\":[1,2]}"));assertEquals("",AudioUnderstanding.context("invalid"));}
    public void testNotePreviewContainsAudibleBoundedPcm()throws Exception {short[] pcm=NotePlayer.render(new JSONArray().put(new JSONObject().put("midi",69).put("start_seconds",0).put("duration_seconds",.5)));assertEquals(8000,pcm.length);int maximum=0;for(short s:pcm)maximum=Math.max(maximum,Math.abs(s));assertTrue(maximum>5000);assertTrue(NotePlayer.render(new JSONArray().put(new JSONObject().put("midi",69).put("start_seconds",100000).put("duration_seconds",1))).length<=320000);}
    private File fixture()throws Exception {File f=File.createTempFile("sound-", ".m4a",getInstrumentation().getTargetContext().getCacheDir());try(InputStream in=getInstrumentation().getContext().getAssets().open("tone.m4a");OutputStream out=new FileOutputStream(f)){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}return f;}
}
